<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap.php';
function pick(array $cells, ?array $headers, ?string $key): ?string { if($key===null||$key==='')return null; if(ctype_digit($key))return isset($cells[(int)$key])?trim($cells[(int)$key]):null; if($headers){$target=normalizeSearch($key); foreach($headers as $i=>$h)if(normalizeSearch($h)===$target)return isset($cells[$i])?trim($cells[$i]):null;} return null; }
function timeMs(?string $raw): ?int { if(!$raw)return null; $v=str_replace(',','.',trim($raw)); if($v===''||preg_match('/^-+$/',$v))return null; $p=explode(':',$v); if(count($p)<2||count($p)>3)return null; foreach($p as $n)if(!is_numeric($n))return null; [$h,$m,$s]=count($p)===3?array_map('floatval',$p):[0,(float)$p[0],(float)$p[1]]; return (int)round(($h*3600+$m*60+$s)*1000); }
function gender(?string $v): ?string { $v=strtoupper(trim($v??'')); return str_starts_with($v,'M')?'M':(str_starts_with($v,'F')?'F':null); }
function genderFromAge(?string $v): ?string { $v=strtoupper(trim($v??'')); return preg_match('/^[MF]\d{2,4}$/',$v)?$v[0]:null; }
function statusOf(?string $v): string { $v=strtoupper(trim($v??'')); if(in_array($v,['DSQ','DQ','DESC','DESCLASSIFICADO','DESCLASSIFICADA','DISQUALIFIED'],true))return 'DSQ'; if(in_array($v,['DNF','NAO COMPLETOU','NÃO COMPLETOU','ABANDONO','ABANDONOU'],true))return 'DNF'; if(in_array($v,['DNS','NAO COMPARECEU','NÃO COMPARECEU','AUSENTE','NAO LARGOU','NÃO LARGOU'],true))return 'DNS'; return 'FINISHED'; }
function rankOf(?string $v): ?int { $v=trim($v??''); if($v===''||preg_match('/^-+$/',$v))return null; $n=(float)str_replace([',','º'],['.',''],$v); return is_finite($n)?(int)$n:null; }
function contentHash(string $s): string { $h1=0x811c9dc5;$h2=0x01000193;$len=strlen($s); for($i=0;$i<$len;$i++){ $c=ord($s[$i]); $h1=(($h1^$c)*16777619)&0xffffffff; $h2=($h2+$c*($i+1))&0xffffffff; } return dechex($h1).'-'.dechex($h2).'-'.$len; }
function parseTiming(string $content,string $type): array { $clean=preg_replace('/^\xEF\xBB\xBF/','',str_replace(["\r\n","\r"],"\n",$content)); $lines=array_values(array_filter(explode("\n",$clean??''),fn($l)=>trim($l)!=='')); if(!$lines)return ['rows'=>[],'errors'=>['Arquivo vazio.']]; array_shift($lines); $isMtb=str_starts_with($type,'MTB');$laps=str_ends_with($type,'COM_VOLTAS');$rows=[];$errors=[];
 foreach($lines as $i=>$line){$c=explode(';',$line);$bib=pick($c,null,'2');$name=pick($c,null,'3');if(!$bib){$errors[]='Linha '.($i+1).': número de peito ausente.';continue;}if(!$name){$errors[]='Linha '.($i+1).': nome do atleta ausente.';continue;}$age=pick($c,null,'5');$time=pick($c,null,'6');$row=['bib_number'=>$bib,'athlete_name'=>trim(preg_replace('/\s+/u',' ',$name)??$name),'name_search'=>normalizeSearch($name),'gender'=>genderFromAge($age),'birth_date'=>null,'category'=>$isMtb?pick($c,null,'0'):null,'age_group'=>$age,'finish_time'=>trim($time??'')?:null,'finish_ms'=>timeMs($time),'finish_clock'=>null,'status'=>'FINISHED','distance'=>pick($c,null,'0'),'team'=>pick($c,null,'7'),'lap'=>$laps?rankOf(pick($c,null,'8')):null,'overall_rank'=>$isMtb?null:rankOf(pick($c,null,'1')),'gender_rank'=>null,'age_group_rank'=>$isMtb?null:rankOf(pick($c,null,'4'))];$rows[$bib]=$row; }
 return ['rows'=>array_values($rows),'errors'=>$errors]; }
function recalcMtb(PDO $pdo,string $eventId): void { $pdo->prepare("UPDATE results SET overall_rank=NULL,gender_rank=NULL,age_group_rank=NULL WHERE event_id=?")->execute([$eventId]); $q=$pdo->prepare("SELECT id,distance,gender,age_group,finish_ms FROM results WHERE event_id=? AND status='FINISHED' AND finish_ms IS NOT NULL ORDER BY distance,finish_ms");$q->execute([$eventId]);$groups=[];foreach($q as $r){foreach(['overall'=>[$r['distance']],'gender'=>[$r['distance'],$r['gender']],'age'=>[$r['distance'],$r['age_group']]] as $kind=>$parts){$k=$kind.'|'.implode('|',$parts);$groups[$k][]=$r;}} $u=$pdo->prepare('UPDATE results SET overall_rank=COALESCE(?,overall_rank),gender_rank=COALESCE(?,gender_rank),age_group_rank=COALESCE(?,age_group_rank) WHERE id=?');foreach($groups as $k=>$list){$kind=strtok($k,'|');$rank=0;$seen=0;$last=null;foreach($list as $r){$seen++;if($last===null||(int)$r['finish_ms']!==$last)$rank=$seen;$last=(int)$r['finish_ms'];$u->execute([$kind==='overall'?$rank:null,$kind==='gender'?$rank:null,$kind==='age'?$rank:null,$r['id']]);}} }
function syncContent(string $eventId,string $content): array { $pdo=db();$start=date('Y-m-d H:i:s.v');$e=$pdo->prepare('SELECT e.*,s.last_file_hash,s.paused FROM events e JOIN sync_configs s ON s.event_id=e.id WHERE e.id=?');$e->execute([$eventId]);$event=$e->fetch();if(!$event)return ['ok'=>false,'processed'=>0,'created'=>0,'updated'=>0,'disqualified'=>0,'removed'=>0,'errors'=>1,'skipped'=>false,'message'=>'Evento ou configuração não encontrados.','finishedAt'=>isoNow(),'connectionStatus'=>'OFFLINE'];$hash=hash('sha256',$content);if(hash_equals((string)($event['last_file_hash']??''),$hash)){$pdo->prepare("UPDATE sync_configs SET last_sync_at=NOW(3),connection_status='ONLINE',last_error=NULL WHERE event_id=?")->execute([$eventId]);return ['ok'=>true,'processed'=>0,'created'=>0,'updated'=>0,'disqualified'=>0,'removed'=>0,'errors'=>0,'skipped'=>true,'message'=>'Arquivo sem alterações desde a última sincronização.','finishedAt'=>isoNow(),'connectionStatus'=>'ONLINE'];}
 $parsed=parseTiming($content,$event['event_type']);if(!$parsed['rows']||$parsed['errors'])return logFailure($pdo,$eventId,$start,$parsed);
 $old=$pdo->prepare('SELECT * FROM results WHERE event_id=?');$old->execute([$eventId]);$existing=[];foreach($old as $r)$existing[$r['bib_number']]=$r;$created=0;$updated=0;$dq=0;$seen=[];$changes=[];$tracked=['athlete_name'=>'Nome','gender'=>'Sexo','birth_date'=>'Nascimento','category'=>'Categoria','age_group'=>'Faixa etária','finish_time'=>'Tempo','finish_clock'=>'Horário de chegada','status'=>'Status','distance'=>'Distância','team'=>'Equipe','lap'=>'Volta','overall_rank'=>'Classificação geral','age_group_rank'=>'Classificação na faixa'];foreach($parsed['rows'] as $r){$bib=$r['bib_number'];$seen[$bib]=true;if(!isset($existing[$bib]))$created++;else{$different=false;foreach($tracked as $field=>$label){$before=(string)($existing[$bib][$field]??'');$after=(string)($r[$field]??'');if($before!==$after){$different=true;$changes[]=[$bib,$r['athlete_name'],$label,$before,$after];}}if($different)$updated++;}if($r['status']==='DSQ')$dq++;}foreach(array_diff_key($existing,$seen) as $bib=>$oldRow)$changes[]=[$bib,$oldRow['athlete_name'],'Presença na classificação','Publicado','Removido (ausente no arquivo atual)'];$removed=count(array_diff_key($existing,$seen));
 try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id FROM events WHERE id=? FOR UPDATE');$lock->execute([$eventId]);$pdo->prepare('DELETE FROM results WHERE event_id=?')->execute([$eventId]);$sql='INSERT INTO results(id,event_id,bib_number,athlete_name,name_search,gender,birth_date,category,age_group,finish_time,finish_ms,finish_clock,status,distance,team,lap,overall_rank,gender_rank,age_group_rank,source) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,\'TXT\')';$ins=$pdo->prepare($sql);foreach($parsed['rows'] as $r)$ins->execute([uuidv4(),$eventId,$r['bib_number'],$r['athlete_name'],$r['name_search'],$r['gender'],$r['birth_date'],$r['category'],$r['age_group'],$r['finish_time'],$r['finish_ms'],$r['finish_clock'],$r['status'],$r['distance'],$r['team'],$r['lap'],$r['overall_rank'],$r['gender_rank'],$r['age_group_rank']]);if(str_starts_with($event['event_type'],'MTB'))recalcMtb($pdo,$eventId);$change=$pdo->prepare("INSERT INTO result_change_logs(id,event_id,bib_number,athlete_name,field,old_value,new_value,source,changed_by) VALUES(?,?,?,?,?,?,?,'Programa local',NULL)");foreach($changes as $item)$change->execute([uuidv4(),$eventId,...$item]);$pdo->prepare("UPDATE sync_configs SET last_file_hash=?,last_sync_at=NOW(3),last_error=NULL,connection_status='ONLINE' WHERE event_id=?")->execute([$hash,$eventId]);$msg=count($parsed['rows']).' atleta(s) publicados com sucesso.'.($removed?" {$removed} atleta(s) saíram da classificação.":'');$pdo->prepare("INSERT INTO sync_logs(id,event_id,started_at,finished_at,source,status,records_processed,records_new,records_updated,records_disqualified,errors,message) VALUES(?,?,?,NOW(3),'AGENT','OK',?,?,?,?,0,?)")->execute([uuidv4(),$eventId,$start,count($parsed['rows']),$created,$updated,$dq,$msg]);$pdo->commit();return ['ok'=>true,'processed'=>count($parsed['rows']),'created'=>$created,'updated'=>$updated,'disqualified'=>$dq,'removed'=>$removed,'errors'=>0,'skipped'=>false,'message'=>$msg,'finishedAt'=>isoNow(),'connectionStatus'=>'ONLINE'];}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();error_log($x->getMessage());return ['ok'=>false,'processed'=>count($parsed['rows']),'created'=>0,'updated'=>0,'disqualified'=>0,'removed'=>0,'errors'=>1,'skipped'=>false,'message'=>'Falha ao gravar. O resultado anterior foi mantido.','finishedAt'=>isoNow(),'connectionStatus'=>'OFFLINE'];}}
function logFailure(PDO $pdo,string $eventId,string $start,array $parsed): array {$msg=!$parsed['rows']?'Arquivo sem atletas válidos. O resultado anterior foi mantido.':'Arquivo rejeitado: '.count($parsed['errors']).' linha(s) inválida(s). O resultado anterior foi mantido.';$pdo->prepare("INSERT INTO sync_logs(id,event_id,started_at,finished_at,source,status,records_processed,errors,message,details) VALUES(?,?,?,NOW(3),'AGENT','ERROR',?,?,?,?)")->execute([uuidv4(),$eventId,$start,count($parsed['rows']),max(1,count($parsed['errors'])),$msg,json_encode(['parse_errors'=>array_slice($parsed['errors'],0,50)],JSON_UNESCAPED_UNICODE)]);$pdo->prepare("UPDATE sync_configs SET connection_status='WARNING',last_error=? WHERE event_id=?")->execute([$parsed['errors'][0]??$msg,$eventId]);return ['ok'=>false,'processed'=>count($parsed['rows']),'created'=>0,'updated'=>0,'disqualified'=>0,'removed'=>0,'errors'=>max(1,count($parsed['errors'])),'skipped'=>false,'message'=>$msg,'finishedAt'=>isoNow(),'connectionStatus'=>'WARNING'];}
